export const FOTOS = {"terreno":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"departamento":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"casa":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"proyecto":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"oficina":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"local":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]}

/** Galeria de 3 fotos para una propiedad, estable segun su indice. */
export function fotosDe(tipo, i = 0) {
  const clave = {
    Departamento: 'departamento', Casa: 'casa', Terreno: 'terreno',
    Oficina: 'oficina', Local: 'local', Proyecto: 'proyecto',
  }[tipo] || 'departamento'
  const banco = FOTOS[clave] || FOTOS.departamento
  return [0, 1, 2].map((k) => banco[(i * 2 + k) % banco.length])
}

/** Una sola foto, para proyectos y cabeceras. */
export function fotoDe(tipo, i = 0) {
  return fotosDe(tipo, i)[0]
}
